[{"order":1,"type":"heading","text":"Advanced Flutter: Method Channels, Platform Views, and FFI"},{"order":2,"type":"paragraph","text":"When building complex Flutter applications, you inevitably reach the boundaries of what pure Dart can do. Whether you need to integrate a native UI component, communicate with platform-specific APIs, or execute high-performance native code synchronously, Flutter provides three powerful mechanisms: Method Channels, Platform Views, and Foreign Function Interface (FFI)."},{"order":3,"type":"heading","text":"1. Method Channels: Asynchronous Platform Messaging"},{"order":4,"type":"paragraph","text":"Method Channels allow you to pass messages between your Dart code and the host platform (iOS and Android) using asynchronous messaging. This is ideal for accessing device hardware, sensors, or platform-specific SDKs."},{"order":5,"type":"subheading","text":"Dart Implementation"},{"order":6,"type":"code","text":"import 'package:flutter/services.dart';

class BatteryService {
  static const MethodChannel _channel = MethodChannel('samples.flutter.dev/battery');

  static Future<String> getBatteryLevel() async {
    try {
      final int result = await _channel.invokeMethod('getBatteryLevel');
      return 'Battery level: $result%';
    } on PlatformException catch (e) {
      return 'Failed to get battery level: '${e.message}';
    }
  }
}"},{"order":7,"type":"subheading","text":"Android (Kotlin) Implementation"},{"order":8,"type":"code","text":"import android.content.Context
import android.os.BatteryManager
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel

class MainActivity : FlutterActivity() {
    private val CHANNEL = "samples.flutter.dev/battery"

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, CHANNEL).setMethodCallHandler {
            call, result ->
            if (call.method == "getBatteryLevel") {
                val batteryLevel = getBatteryLevel()
                if (batteryLevel != -1) {
                    result.success(batteryLevel)
                } else {
                    result.error("UNAVAILABLE", "Battery level not available.", null)
                }
            } else {
                result.notImplemented()
            }
        }
    }

    private fun getBatteryLevel(): Int {
        val batteryManager = getSystemService(Context.BATTERY_SERVICE) as BatteryManager
        return batteryManager.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)
    }
}"},{"order":9,"type":"heading","text":"2. Platform Views: Embedding Native UI"},{"order":10,"type":"paragraph","text":"Platform Views enable you to embed native Android (AndroidView) and iOS (UiKitView) components directly inside your Flutter widget tree. This is essential for rendering native maps, web views, or complex platform-specific controls."},{"order":11,"type":"subheading","text":"Dart Usage of AndroidView"},{"order":12,"type":"code","text":"import 'package:flutter/material.dart';

class NativeViewExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return AndroidView(
      viewType: 'native-view-type',
      layoutDirection: TextDirection.ltr,
      creationParams: <String, dynamic>{'text': 'Hello from Flutter'},
      creationParamsCodec: const StandardMessageCodec(),
    );
  }
}"},{"order":13,"type":"heading","text":"3. Dart FFI: High-Performance C/C++ Integration"},{"order":14,"type":"paragraph","text":"Method channels use serialization and operate asynchronously, which can introduce overhead. Dart FFI (Foreign Function Interface) allows you to call native C/C++ libraries synchronously, making it ideal for intensive computations, image processing, or game engines."},{"order":15,"type":"subheading","text":"Defining a C Function"},{"order":16,"type":"code","text":"#include <stdint.h>

extern "C" {
    __attribute__((visibility("default"))) __attribute__((used))
    int32_t add(int32_t a, int32_t b) {
        return a + b;
    }
}"},{"order":17,"type":"subheading","text":"Calling C from Dart via FFI"},{"order":18,"type":"code","text":"import 'dart:ffi' as ffi;
import 'dart:io' as io;

// 1. Define function signature types
typedef NativeAddFunc = ffi.Int32 Function(ffi.Int32 a, ffi.Int32 b);
typedef DartAddFunc = int Function(int a, int b);

class NativeCalculator {
  late final DartAddFunc _add;

  NativeCalculator() {
    // 2. Load the dynamic library
    final ffi.DynamicLibrary nativeLib = io.Platform.isAndroid
        ? ffi.DynamicLibrary.open('libnative.so')
        : ffi.DynamicLibrary.executable();

    // 3. Look up the function and bind it to a Dart callable
    _add = nativeLib
        .lookup<ffi.NativeFunction<NativeAddFunc>>('add')
        .asFunction<DartAddFunc>();
  }

  int compute(int a, int b) {
    return _add(a, b);
  }
}"},{"order":19,"type":"heading","text":"Summary and Best Practices"},{"order":20,"type":"bullet_point","text":"Use Method Channels for general asynchronous control, events, and accessing high-level platform APIs."},{"order":21,"type":"bullet_point","text":"Use Platform Views sparingly for embedding complex native UI components that do not have a robust Flutter equivalent."},{"order":22,"type":"bullet_point","text":"Use Dart FFI for CPU-bound tasks, algorithms, or when integrating existing C/C++ codebases with zero serialization overhead."}]
